import { ChangeDetectionStrategy, Component, computed, input, signal } from '@angular/core';

@Component({
  selector: 'aevko-avatar',
  standalone: true,
  templateUrl: './avatar.component.html',
  styleUrl: './avatar.component.css',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { 'data-slot': 'avatar', '[style.--aevko-avatar-size]': 'size()' },
})
export class AevkoAvatar {
  readonly src = input<string | null>(null);
  readonly alt = input.required<string>();
  readonly fallback = input.required<string>();
  readonly size = input('2.5rem');
  protected readonly failed = signal(false);
  protected readonly showImage = computed(() => Boolean(this.src()) && !this.failed());
}

:host {
  background: var(--aevko-surface, #f4f4f5);
  border: 1px solid var(--aevko-border, #e4e4e7);
  display: inline-grid;
  height: var(--aevko-avatar-size, 2.5rem);
  overflow: hidden;
  place-items: center;
  width: var(--aevko-avatar-size, 2.5rem);
}
img {
  height: 100%;
  object-fit: cover;
  width: 100%;
}
.fallback {
  align-items: center;
  display: flex;
  font-size: calc(var(--aevko-avatar-size, 2.5rem) * 0.34);
  font-weight: 600;
  height: 100%;
  justify-content: center;
  text-transform: uppercase;
  width: 100%;
}
